@startuml

class SensorController {
  + username : string
  + password : string
}

class Apartment {
  + address : string
  + rooms : Room[]
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorId : int
  + description : string
  + unit : string
  + room : Room
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + counterReading : float
}

class Value {
  + timestamp : datetime
  + value : float
}

class SensorThreshold {
  + sensor : Sensor
  + thresholdValue : float
  + emailAddress : string
}

abstract class System {
  + sendAlert(message: string) : void
}

class EMonitor extends System {}

SensorController "1" -- "*" Apartment
Apartment "1" *-- "* Room"
Room "0..*" -- "1 Sensor"
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor
SensorController "1" -- "*" Value
Value "1" -- "1 Sensor"
SensorThreshold "1" -- "1 Sensor"

EMonitor ..> System

@enduml

